class Collection extends Map {}

class MessageEmbed {
  setTitle() { return this; }
  setDescription() { return this; }
  setColor() { return this; }
}

class Client {
  constructor() {
    this.events = new Map();
    this.user = {
      id: '0',
      tag: 'local#0000',
      setActivity: () => {},
    };
    this.commands = new Collection();
    this.aliases = new Collection();
  }

  on(event, handler) {
    this.events.set(event, handler);
  }

  once(event, handler) {
    this.events.set(event, handler);
  }

  login(_token) {
    const ready = this.events.get('ready');
    if (typeof ready === 'function') ready();
    return Promise.resolve('local-token');
  }
}

module.exports = {
  Discord: { Client, Collection },
  Client,
  Intents: { FLAGS: {} },
  Collection,
  MessageEmbed,
};
